// ---------------------------------------------------------------------------
// WF3 · Paso 2: preparar las aperturas de seguimiento (D25, D30, D36.2). 2026-10-19.
// Entrada (1 elemento): la PRIMERA lectura de GET /llamadas-del-dia.
// Salida: 1 elemento { oportunidad_id } por cada seguimiento POR ABRIR (apartado b),
//         o 1 elemento { sin_aperturas: true } si no hay ninguno.
// Mode: Run Once for All Items. Determinista: ningún LLM interviene.
// ---------------------------------------------------------------------------
// La lista del backend (un solo elemento).
const lista = $input.first().json;
// El apartado b); "?? []": si faltara, una lista vacía en vez de romper.
const porAbrir = lista.seguimientos_por_abrir ?? [];
// Nada que abrir: un solo elemento que lo dice (hay_aperturas salta a la relectura).
if (porAbrir.length === 0) return [{ json: { sin_aperturas: true } }];
// Solo el número de oportunidad: el endpoint no necesita nada más (minimización).
return porAbrir.map((e) => ({ json: { oportunidad_id: e.oportunidad_id } }));

// ---------------------------------------------------------------------------
// WF3 · Paso 2: evaluar las respuestas de POST /create-followup-task (D36.2). 2026-10-19.
// Entrada: 1 respuesta COMPLETA { statusCode, body } por apertura, en el MISMO orden
//   que preparar_aperturas; o { error } si no hubo respuesta (onError: continuar).
//   201 abierto ahora · 200 ya estaba abierto (reintento) · 409 carrera normal
//   (p. ej. el cliente pidió visita a las 7:59): ninguno de los tres es un fallo.
//   401, 404, 422, 503, 500 o sin respuesta: fallo técnico -> aviso a WF4.
// Un fallo NO para el email: ese caso sigue en "por abrir", sale en la lista de hoy
// y WF3 lo vuelve a intentar mañana (el endpoint es idempotente).
// Salida (1 elemento): recuentos + los 5 datos de WF4 (sin datos del cliente).
// Mode: Run Once for All Items. Determinista: ningún LLM interviene.
// ---------------------------------------------------------------------------
// Los números que se pidieron, en orden (el número no es un dato personal).
const pedidas = $('preparar_aperturas').all().map((i) => i.json.oportunidad_id);
// Lo que contestó el backend, en el mismo orden.
const respuestas = $input.all().map((i) => i.json);

// Texto de un error de n8n sin el objeto entero (podría llevar la petición).
function textoError(e) {
  if (!e) return 'sin respuesta';                                 // no llegó nada
  if (typeof e === 'string') return e;                            // ya es un texto
  // code, message y description, solo los que sean textos no vacíos.
  const partes = [e.code, e.message, e.description].filter((x) => typeof x === 'string' && x.trim() !== '');
  return partes.length > 0 ? partes.join(' · ') : 'error sin texto';
}

let abiertos = 0, ya_abiertos = 0, carreras = 0;                  // recuentos de lo normal
const fallos = [];                                                // "oportunidad: qué pasó"
respuestas.forEach((r, i) => {
  const codigo = r.statusCode;                                    // undefined si no hubo respuesta
  if (codigo === 201) abiertos += 1;                              // abierto ahora
  else if (codigo === 200) ya_abiertos += 1;                      // ya estaba abierto
  else if (codigo === 409) carreras += 1;                         // la situación cambió: normal
  else fallos.push(`${pedidas[i]}: ${codigo ?? textoError(r.error)}`);  // fallo técnico
});
// Defensa: si faltan respuestas, también es un fallo (no debería pasar nunca).
if (respuestas.length !== pedidas.length) fallos.push(`${respuestas.length} respuestas de ${pedidas.length} peticiones`);

// Un solo elemento: lo que se hizo y, si hace falta, el aviso para WF4.
return [{ json: {
  abiertos, ya_abiertos, carreras, fallos: fallos.length,         // para comprobarlo en las pruebas
  aviso: fallos.length > 0,                                       // lo lee hay_fallo_apertura
  flujo: $workflow.name,                                          // los 5 datos de WF4...
  nodo: 'abrir_seguimiento',
  mensaje_error: fallos.length === 0 ? '' :
    `POST /create-followup-task falló en ${fallos.length} de ${pedidas.length}: ${fallos.join(' | ')}. ` +
    'Esos casos siguen en "por abrir" (salen en la lista de hoy) y WF3 los reintentará mañana.',
  oportunidad_id: null,                                           // pueden ser varias: van en el texto
  ejecucion_id: String($execution.id),                            // para buscar la ejecución
} }];

// ---------------------------------------------------------------------------
// WF3 · Construir el email de la lista diaria de llamadas para administración.
// 2026-10-19 (D30, D36.1): apartado "Última llamada" al principio. Un caso con
//   DIAS_ULTIMA_LLAMADA días o más desde el presupuesto SALE de su bloque y
//   aparece SOLO ahí: cada llamada, una sola vez. Entra desde a), b) y c).
//   La entrada es ahora la SEGUNDA lectura (releer_llamadas_del_dia), hecha
//   después de abrir los seguimientos del paso 2: el email refleja la base de datos.
// 2026-10-22 (D41.1): email 3 (recordatorio) SOLO en la ejecución automática; la
//  lista dice si el recordatorio salió por email o hay que llamar.
// 2026-10-23 (D43.6, D44): botón "Registrar llamada" en cada llamada que se puede
//  registrar (H-UX-1), a la pantalla de llamadas (WF_pantalla_llamadas) con el número
//  puesto y la marca ultima=1 / ultima=0. La pantalla NO calcula la última llamada:
//  la decide SOLO este nodo (DIAS_ULTIMA_LLAMADA), una sola fuente (D44).
// Entrada ($json): la respuesta de GET /llamadas-del-dia (cinco apartados).
// Salida: { asunto, html, total }.
// Determinista: ningún LLM interviene. Todo dato variable pasa por esc().
// Decisiones: D25.2 (una lista al día), D25.8 (Gate y seguimiento en la misma
// lista, con la etiqueta del motivo), D26.3 (visitas d y e en UN bloque),
// D28.2 (enlace a la ficha en cada elemento), D29.4 ("hace X días").
// Minimización (D26.1): la lista ACUMULA clientes en un solo mensaje, así que
// solo lleva nombre, teléfono y el resumen de la solicitud. Sin email ni
// importes: están en la ficha, detrás de la contraseña.
// ---------------------------------------------------------------------------

// ---- 1. La respuesta del backend --------------------------------------------
const L = $json;
// Los cinco apartados; "?? []" = si faltara alguno, una lista vacía (sin romper).
const gates = L.gates_sin_decision ?? [];
const segPorAbrir = L.seguimientos_por_abrir ?? [];
const segAbiertos = L.seguimientos_abiertos ?? [];
const visSinConfirmar = L.visitas_sin_confirmar ?? [];
const visProximoDia = L.visitas_proximo_laborable ?? [];

// ---- 1c. Recordatorios por email (email 3, D39.1 y D41.1, 2026-10-22) -------
// Solo una ejecución AUTOMÁTICA (la de las 8:00) envía los recordatorios. Una
// ejecución lanzada a mano desde el editor nunca los envía, se lance desde el
// disparador que se lance, así que repetir WF3 a mano no manda un segundo email
// al cliente. $execution.mode vale 'production' en las automáticas y 'test' en
// las manuales (documentación de n8n, "n8n metadata").
const programada = $execution.mode === 'production';
// ¿Recibe este cliente el recordatorio por email? Visita CONFIRMADA del próximo
// laborable, ejecución programada y contacto de la solicitud (la misma regla G3
// de WF7: sin contacto, WF7 no envía nada).
const recordatorioPorEmail = (e) => programada && e.estado_visita === 'confirmada'
  && e.contacto?.origen === 'solicitud';
// Los números de oportunidad a los que WF7 enviará el recordatorio (lo lee preparar_recordatorios).
const recordatorios = visProximoDia.filter(recordatorioPorEmail).map((e) => e.oportunidad_id);

// ---- 1b. Umbral de la última llamada (D30) ------------------------------------
// Una sola constante con nombre (D30). Deuda N1: pasarla a reglas_negocio (D13).
const DIAS_ULTIMA_LLAMADA = 7;

// ---- 2. Dirección pública de la ficha (D26.8) -------------------------------
// Constante aquí porque n8n 2.x bloquea leer variables de entorno desde un nodo
// Code. Si cambia el dominio de ngrok, se cambia SOLO esta línea (deuda técnica
// conocida, la misma que en WF2 y en la página de la ficha).
const DOMINIO = 'https://TU-DOMINIO.ngrok-free.dev';
const FICHA_BASE = `${DOMINIO}/webhook/ficha`;
// D43.6: la pantalla de llamadas (mismo dominio; un solo sitio donde cambiarlo).
const REGISTRO_BASE = `${DOMINIO}/webhook/llamada`;

// ---- 3. Colores de la empresa (los mismos que WF2 y la ficha) ---------------
const AZUL = '#0B3C5D';            // cabecera, títulos y teléfonos
const TURQUESA = '#1F8A8A';        // acentos y enlaces a la ficha
const TURQUESA_CLARO = '#E3F2F1';  // línea bajo los títulos
const FONDO = '#EEF3F6';           // gris azulado alrededor de la tarjeta
const TEXTO = '#1F2933';           // texto principal
const SUAVE = '#5B6B79';           // texto secundario
const AMBAR = '#B45309';           // etiqueta GATE (lo más urgente)
const ROJO = '#9B1C1C';            // etiqueta ÚLTIMA LLAMADA (D30): cierra el caso

// ---- 4. Escapar texto antes de meterlo en HTML -------------------------------
// Nombres y textos de visitas los escribieron clientes o el agente: esc()
// cambia los caracteres especiales de HTML por su forma inofensiva.
function esc(valor) {
  return String(valor)
    .replace(/&/g, '&amp;')    // el & primero, para no estropear los siguientes
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// ---- 5. Formatos españoles (solo para MOSTRAR) ------------------------------
// Números sin ceros sobrantes: "10.0" -> "10", "12.35" -> "12,35".
const num = new Intl.NumberFormat('es-ES', { maximumFractionDigits: 2 });
// Fecha y hora -> "07/10/2026, 14:00" en hora de Madrid; si falta, un guion.
function fecha(t) {
  if (!t) return '—';
  return new Date(t).toLocaleString('es-ES', {
    timeZone: 'Europe/Madrid', day: '2-digit', month: '2-digit', year: 'numeric',
    hour: '2-digit', minute: '2-digit',
  });
}
// Un día sin hora ("2026-10-12") -> "lunes, 12/10/2026". Se fija el mediodía
// UTC para que el cambio de hora nunca lo mueva al día anterior.
function diaLargo(isoDia) {
  if (!isoDia) return '—';
  return new Date(`${isoDia}T12:00:00Z`).toLocaleDateString('es-ES', {
    timeZone: 'Europe/Madrid', weekday: 'long', day: '2-digit', month: '2-digit', year: 'numeric',
  });
}
// Días enteros desde una fecha hasta ahora (86.400.000 ms = 1 día).
// Math.floor redondea hacia abajo: 1,9 días cuenta como 1.
function diasDesde(t) {
  return Math.floor((Date.now() - new Date(t).getTime()) / 86400000);
}
// 0 -> "hoy", 1 -> "hace 1 día", n -> "hace n días".
function haceDias(t) {
  const n = diasDesde(t);
  return n <= 0 ? 'hoy' : n === 1 ? 'hace 1 día' : `hace ${n} días`;
}

// ---- 6. Diccionarios: códigos del backend -> texto legible ------------------
const TIPOS = { bano: 'Baño', cocina: 'Cocina', integral_vivienda: 'Reforma integral',
  parcial_acabados: 'Acabados parciales' };
const ACABADOS = { basico: 'básico', medio: 'medio', alto: 'alto' };

// ---- 7. Piezas del contenido de cada llamada ---------------------------------
// Resumen de la solicitud (D26.1). Ningún "null" a la vista: si falta un dato,
// se dice que no se indicó (R5 del plan del resumen).
function resumen(s) {
  const m2 = (s.m2 === null || s.m2 === undefined) ? 'm² no indicados' : `${num.format(Number(s.m2))} m²`;
  const acabados = s.nivel_acabados
    ? `acabados ${ACABADOS[s.nivel_acabados] ?? s.nivel_acabados}` : 'acabados no indicados';
  const cambios = s.incluye_cambios_estructurales === true ? 'con cambios estructurales'
    : s.incluye_cambios_estructurales === false ? 'sin cambios estructurales'
    : 'cambios estructurales no indicados';
  return `${m2} · ${acabados} · ${cambios}`;
}
// Nombre y teléfono. El teléfono es un enlace "tel:" (en el móvil, un toque
// llama). Si la solicitud no trae contacto (leads anteriores al 25/09), se
// remite a la ficha.
function contacto(c) {
  if (!c || c.origen !== 'solicitud') {
    return `<span style="color:${SUAVE};">Contacto no disponible en la solicitud: ver la ficha</span>`;
  }
  // El número sin espacios para el enlace; tal cual para mostrarlo.
  const tel = c.telefono
    ? `<a href="tel:${esc(String(c.telefono).replace(/\s+/g, ''))}" style="color:${AZUL};font-weight:bold;text-decoration:none;">${esc(c.telefono)}</a>`
    : 'teléfono no indicado';
  return `<b>${esc(c.nombre ?? 'Nombre no indicado')}</b> · ${tel}`;
}
// Enlace a la ficha completa de esa oportunidad (D28.2).
function enlaceFicha(id) {
  const url = `${FICHA_BASE}?oportunidad_id=${encodeURIComponent(id)}`;
  return `<a href="${esc(url)}" style="color:${TURQUESA};font-weight:bold;">Ver ficha completa</a>`;
}
// D43.6 (H-UX-1): botón a la pantalla de llamadas con el número ya puesto.
// ultima: true -> "&ultima=1"; false -> "&ultima=0"; null -> sin marca (visitas:
// la última llamada no existe en las confirmaciones, D30).
function botonRegistrar(id, ultima) {
  // La marca, solo si se sabe (D44).
  const marca = ultima === true ? '&ultima=1' : ultima === false ? '&ultima=0' : '';
  // La dirección completa, con el número codificado.
  const url = `${REGISTRO_BASE}?oportunidad_id=${encodeURIComponent(id)}${marca}`;
  // Botón hecho con un enlace (los clientes de correo no admiten botones de verdad).
  return `<a href="${esc(url)}" style="display:inline-block;background:${AZUL};color:#FFFFFF;font-weight:bold;font-size:13px;padding:6px 14px;border-radius:5px;text-decoration:none;margin-right:12px;">Registrar llamada</a>`;
}
// Una llamada: etiqueta de color, oportunidad y tipo, contacto, resumen, una
// línea propia de su apartado (extraHtml, ya escapada), el botón "Registrar llamada"
// (registro: { ultima } o null = sin botón) y el enlace a la ficha.
function llamada(etiqueta, color, e, extraHtml, registro = null) {
  const tipo = TIPOS[e.tipo_reforma] ?? e.tipo_reforma ?? 'tipo no indicado';
  return `<tr><td style="padding:12px 0;border-bottom:1px solid #E5E9ED;">
    <div style="font-size:12px;">
      <span style="background:${color};color:#FFFFFF;padding:2px 8px;border-radius:10px;font-weight:bold;">${esc(etiqueta)}</span>
      <span style="color:${SUAVE};margin-left:6px;">Oportunidad ${esc(e.oportunidad_id)} · ${esc(tipo)}</span>
    </div>
    <div style="font-size:15px;margin-top:6px;">${contacto(e.contacto)}</div>
    <div style="font-size:13px;margin-top:4px;">${esc(resumen(e.solicitud ?? {}))}</div>
    ${extraHtml}
    <div style="font-size:13px;margin-top:8px;">${registro ? botonRegistrar(e.oportunidad_id, registro.ultima) : ''}${enlaceFicha(e.oportunidad_id)}</div>
  </td></tr>`;
}
// Una línea gris pequeña (ya escapada dentro).
function nota(texto) {
  return `<div style="font-size:12px;color:${SUAVE};margin-top:4px;">${esc(texto)}</div>`;
}
// Un bloque: título con su número de llamadas, una explicación y las llamadas.
// Si no hay ninguna, el bloque no se pinta.
function bloque(titulo, explicacion, filas) {
  if (filas.length === 0) return '';
  return `<tr><td style="padding:20px 32px 0;">
    <div style="font-size:13px;letter-spacing:1px;text-transform:uppercase;color:${TURQUESA};font-weight:bold;border-bottom:2px solid ${TURQUESA_CLARO};padding-bottom:6px;">${esc(titulo)} (${filas.length})</div>
    <div style="font-size:12px;color:${SUAVE};margin-top:6px;">${esc(explicacion)}</div>
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0">${filas.join('')}</table>
  </td></tr>`;
}

// ---- 8. Última llamada (D30, D36.1): separar ANTES de pintar los bloques -------
// ¿Lleva DIAS_ULTIMA_LLAMADA días o más desde el presupuesto? Se usa diasDesde,
// el MISMO cálculo que "hace X días": lo que dice el email y el apartado coinciden.
// Sin fecha_presupuesto se queda en su bloque: new Date(null) es el 1/1/1970 y
// contaría como "20.000 días" (fallo encontrado en la simulación del tutor).
const esUltima = (e) => Boolean(e.fecha_presupuesto) && diasDesde(e.fecha_presupuesto) >= DIAS_ULTIMA_LLAMADA;
// Cada lista se parte en dos, la de última llamada y la normal: nada se repite.
const gatesUltima = gates.filter(esUltima);
const gatesNormal = gates.filter((e) => !esUltima(e));
const porAbrirUltima = segPorAbrir.filter(esUltima);
const porAbrirNormal = segPorAbrir.filter((e) => !esUltima(e));
const abiertosUltima = segAbiertos.filter(esUltima);
const abiertosNormal = segAbiertos.filter((e) => !esUltima(e));

// Las de última llamada juntas, de la MÁS ANTIGUA a la más reciente; cada una
// recuerda de qué apartado viene (Gate o seguimiento) para su etiqueta.
const ultimas = [
  ...gatesUltima.map((e) => ({ e, origen: 'Gate' })),
  ...[...porAbrirUltima, ...abiertosUltima].map((e) => ({ e, origen: 'Seguimiento' })),
].sort((x, y) => new Date(x.e.fecha_presupuesto) - new Date(y.e.fecha_presupuesto));
// Qué hacer, con las mismas palabras que el formulario (página "Motivo de descarte").
const filasUltima = ultimas.map(({ e, origen }) => llamada(`Última llamada · ${origen}`, ROJO, e,
  nota(`Presupuesto del ${fecha(e.fecha_presupuesto)} (${haceDias(e.fecha_presupuesto)}), sin respuesta. ` +
       'Si sigue sin decidirse, regístralo como Descartar con el motivo "Sigue sin decidirse (última llamada)".'),
  { ultima: true }));   // D44: la pantalla mostrará el aviso de última llamada

// ---- 8b. Los bloques de siempre, ya SIN los casos de última llamada --------------
// a) Gate sin decisión: lo de más importe y riesgo, primero.
const filasGate = gatesNormal.map((e) => llamada('GATE', AMBAR, e,
  nota(`Presupuesto del ${fecha(e.fecha_presupuesto)} (${haceDias(e.fecha_presupuesto)}), sin resultado registrado.`),
  { ultima: false }));  // D44: todavía no es la última llamada

// d) y e) en UN bloque (D26.3), ordenadas por la fecha de la visita. Las visitas
// no tienen última llamada (D30 solo cuenta presupuestos sin respuesta).
// "..." junta las dos listas en una; sort las ordena de la más próxima a la más lejana.
const visitas = [...visSinConfirmar, ...visProximoDia]
  .sort((x, y) => new Date(x.fecha_visita) - new Date(y.fecha_visita));
const filasVisitas = visitas.map((e) => {
  // Etiqueta según el estado de la visita y el apartado de donde viene.
  const esProximoDia = e.motivo === 'visita_proximo_laborable';
  const etiqueta = e.estado_visita === 'confirmada' ? 'Visita confirmada'
    : esProximoDia ? 'Por confirmar (próxima)' : 'Por confirmar';
  // Qué hacer: confirmar la cita o recordarla.
   // D41.1 (2026-10-22): una visita confirmada del próximo laborable ya no se recuerda
  // por teléfono si el email de recordatorio ha salido en esta ejecución.
  const accion = e.estado_visita !== 'confirmada' ? 'Llamar para confirmar la fecha y hora pedidas.'
    : recordatorioPorEmail(e) ? 'Recordatorio enviado al cliente por email: no hace falta llamar (solo si llega un aviso técnico de que no ha salido).'
    : esProximoDia ? 'Recordar la visita al cliente por teléfono (hoy no se ha enviado el email de recordatorio).'
    : 'Recordar la visita al cliente.';
  // El texto de la visita (resumen del agente o texto del sistema), con sus
  // saltos de línea convertidos en <br> DESPUÉS de escaparlo.
  const texto = `<div style="font-size:13px;background:#F6F8FA;border-radius:4px;padding:6px 10px;margin-top:6px;">${esc(e.texto_cliente ?? '').replace(/\r?\n/g, '<br>')}</div>`;
  // Botón solo en las visitas POR CONFIRMAR: una confirmada no tiene llamada que registrar.
  return llamada(etiqueta, TURQUESA, e,
    nota(`Visita: ${fecha(e.fecha_visita)}. ${accion}`) + texto,
    e.estado_visita !== 'confirmada' ? { ultima: null } : null);
});

// b) y c): seguimientos, con la etiqueta del motivo (D25.8) y los días (D29.4).
const filasSeg = [
  ...porAbrirNormal.map((e) => llamada('1.ª llamada de seguimiento', AZUL, e,
    nota(`Presupuesto enviado el ${fecha(e.fecha_presupuesto)} (${haceDias(e.fecha_presupuesto)}), sin respuesta del cliente.`),
    { ultima: false })),   // D44
  ...abiertosNormal.map((e) => llamada('Seguimiento abierto', AZUL, e,
    nota(`Presupuesto enviado el ${fecha(e.fecha_presupuesto)} (${haceDias(e.fecha_presupuesto)}). Lleva en seguimiento desde entonces.`),
    { ultima: false })),   // D44
];

// ---- 9. Cabecera, recuento y asunto ------------------------------------------
const total = gates.length + segPorAbrir.length + segAbiertos.length
  + visSinConfirmar.length + visProximoDia.length;
// Fecha de la lista: el día de generado_en, en Madrid.
const hoy = new Date(L.generado_en ?? Date.now()).toLocaleDateString('es-ES', {
  timeZone: 'Europe/Madrid', weekday: 'long', day: '2-digit', month: '2-digit',
});
// Asunto SIN nombres de clientes (RGPD: los asuntos salen en las notificaciones).
const asunto = total === 0
  ? `[Llamadas del día] ${hoy} · sin llamadas pendientes`
  : `[Llamadas del día] ${hoy} · ${total} ${total === 1 ? 'llamada' : 'llamadas'}`
    + (ultimas.length ? ` · ${ultimas.length} de última llamada` : '')   // D36.1: aparte
    + (gatesNormal.length ? ` · ${gatesNormal.length} con Gate` : '');   // Gate sin las de última llamada

// Línea de recuento bajo el título.
const recuento = total === 0
  ? 'Hoy no hay llamadas pendientes. Este email confirma que la revisión diaria se ha hecho.'
  : `${ultimas.length} de última llamada · ${gatesNormal.length} de Gate · ${visitas.length} de visitas · ${filasSeg.length} de seguimiento.`;

// Pie: las reglas con las que se ha hecho la lista (transparencia: se cambian en
// reglas_negocio, sin tocar el flujo) y el aviso de uso interno.
const reglas = L.reglas ?? {};
const pie = `Plazos aplicados: Gate a las ${esc(reglas.horas_recordatorio_gate ?? '—')} h y seguimiento a las `
  + `${esc(reglas.horas_seguimiento_presupuesto ?? '—')} h desde el presupuesto. Visitas del próximo día laborable: `
